        "whyItMatters": "从 1904 年到 1928 年的作品跨度、战争造成的社交断裂和复制媒介中的跨团体流通共同说明，Klee 的面具不是一把通往人物内心的固定钥匙，而是一套会随历史和媒介改变的视觉语法。可以选取眼睛、嘴、轮廓和姿态四类抽象部件，制作不复制原作的组合图，再比较同一组部件进入剧场、漫画、摄影与印刷页面后，观看者如何赋予它不同身份。"
