        "whyItMatters": "新委托、社群协作和纺织材料的可触摸性把纪念权从单一英雄、建筑师或国家机构分散给制作者、劳动者和被纪念者。可以为一件虚构的公共纪念物分别绘制石材版本与织物版本，标出材料来源、制作时间、修补责任、触摸规则和谁能修改内容，再比较“长久不变”与“持续被照护”各自让哪些历史可见。"
