        "summary": "社会资本指人们能通过关系网接触到的信息、职业和其他资源。一项比较二十九个社会的研究发现，网络多样性尤其是强关系的多样性与较高收入相关；女性在部分网络资源上处于较低位置，但相似关系网在不同制度和文化中并不会产生同样的性别收入结果。",
