        "title": "把筛查带回家仍不够：自主、隐私与被肯定的沟通必须同时存在",
        "summary": "跨男性或跨阳刚气质者中，部分人仍保留宫颈并需要宫颈癌筛查。一项九人质性研究发现，居家高危人乳头瘤病毒自取样因自主和隐私而具有吸引力，但能否接受还取决于性别焦虑、既往医疗伤害、费用、清楚说明以及筛查结果能否接上肯定性照护。",
        "background": "高危人乳头瘤病毒是多数宫颈癌的必要致病因素。居家自取样允许符合筛查条件的人自己采集样本，再交由实验室检测；它改变的是取样地点和控制权，并不会自动完成结果解释、复查或治疗。筛查资格应依据实际器官与临床史，而不是只看法律性别字段。",
        "happened": "《Western Journal of Nursing Research》于 8 月 9 日在线发表研究。研究者在 2022 至 2023 年以半结构式访谈了解九名跨男性参与者的筛查经验。参与者普遍重视居家自取样的自主性和隐私，但接受度是有条件的，仍受到医疗空间排斥、提供者支持、社会网络和后续照护设计影响。",
