          "研究采用目的抽样，共访问 9 名参与者。",
          "访谈在 2022 至 2023 年间进行。",
          "研究使用深入半结构式访谈与主题分析。",
          "反复出现的障碍包括性别焦虑、负面医疗经历和排斥性的医疗空间。",
          "提供者支持与社会网络既可能促进，也可能阻碍筛查。",
          "参与者重视居家高危 HPV 自取样带来的自主性与隐私。",
          "肯定性沟通、具备文化能力的提供者、针对性教育、费用与保险覆盖会影响可接受性。",
          "居家自取样是有条件的选择，并不代表每位符合条件的人都偏好在家完成。",
