        "title": "微休息不只看多长：主动做事、社交与走动对应不同的能量轮廓",
        "summary": "微休息是工作任务之间短暂离开主要工作的活动。一项对九十一名员工的一日追踪，把数百个小时片段分成主动、社交、走动、整理与被动五类；主动、社交和走动时段与较高的当下活力相关，但研究没有证明安排某类休息必然造成长期改善。",
        "background": "以往研究常把休息按时长或是否离开任务分类。新研究改为同时记录一小时内做了什么、主观活力与疲劳、内在动机和心率变异性，再用潜在剖面方法寻找经常一起出现的活动组合。",
        "happened": "《Journal of Business and Psychology》于 7 月 24 日在线发表研究，University of Queensland 于 8 月 7 日发布说明。团队发现，被动活动占观察时段近三分之二，但主动、社交和走动类型与更高活力同时出现；员工也并不固定属于某一种类型，约四分之三的人会在一天内切换策略。",
        "facts": [
          "样本包含 91 名员工。",
          "参与者在一个工作日内每小时填写一次体验报告，并佩戴动态心率监测设备。",
          "每人平均提供 6.62 个小时片段，合计约六百个小时片段。",
          "五类片段分别为主动 6%、社交 15%、走动 5%、有意义的整理 9% 与被动 65%。",
          "主动、社交和走动片段报告的活力高于有意义的整理与被动片段。",
          "五类片段的疲劳没有显著差异。",
          "走动片段的心率变异性高于有意义的整理、被动和主动片段。",
          "主动片段的内在动机与工作掌握感高于其他四类。",
          "约 74% 的参与者在一天中切换过片段类型。",
          "小时层面的关联与有限的滞后结果不能证明某类微休息单独造成随后表现改善。"
        ],
        "sourceName": "Journal of Business and Psychology／工作日能量管理策略研究",
        "sourceUrl": "https://link.springer.com/article/10.1007/s10869-026-10143-x",
        "sourceDate": "论文在线发表 2026-07-24；研究说明 2026-08-07；DOI 10.1007/s10869-026-10143-x",
        "whyItMatters": "65% 的被动片段、约 74% 的日内切换，以及活力有差异而疲劳无显著差异共同说明，“休息”不是一剂效果固定的单一行为。可以把同一工作日做成可切换的五轨时间轴，同时记录任务控制权、空间限制、照护责任和主管规范，继续比较员工是否有条件选择走动或社交，而不是把能量管理再次变成个人自律要求。"
