          "参与者年龄中位数为 30 岁，范围为 19 至 55 岁。",
          "22 人已婚，21 人出生于阿富汗，2 人出生于伊朗。",
          "21 人主要使用达里语，2 人主要使用普什图语。",
          "参与者在美国居住时间中位数为 4 年，范围为 1 至 17 年。",
          "16 人报告有医疗保险，1 人无保险，6 人保险状态不详。",
          "访谈持续 30 至 60 分钟，以英语或达里语完成。",
          "达里语访谈由双语研究者解释并独立复核，主题也与阿富汗移民社群成员共同审阅。",
          "样本通过社区组织与口碑便利和目的抽样取得，不能用于估计所有阿富汗难民女性中各障碍的发生率。"
