          "WR 137 由约 10 个太阳质量的 Wolf-Rayet 星和约 17 个太阳质量的伴星组成，公转周期为 13.1 年。",
          "WR 137 的内侧约 100 至 200 天文单位尘埃呈线性结构，而不是预期中的完整螺旋。",
          "PDS 70 距离地球约 370 光年，年龄约 500 万年。",
