        "whyItMatters": "临时立面、混合材料小样、数字扫描、铸造、人工着色和信托收购共同说明，一件被称为个人作品的雕塑也依赖多人技术与长期收藏资金。可以把作品的地理与材料迁移画成双线：一条追踪 New York 立面到 Iowa 馆藏，另一条追踪漂流木与珠饰小样到青铜表面，并继续追问馆藏说明如何既承认跨文化引用，又避免把不同原住民传统合并成单一符号。"
