        "whyItMatters": "34 位负责人、公开数据政策和跨设施时段说明，天文基础设施至少有三层：仪器收集数据、档案开放数据、评审系统配置把数据转成知识所需的劳动与观测资源。可以选取一项入选研究，画出伽马射线事件从卫星、地面处理、公共档案、提案评审到其他波段望远镜的旅程，并比较科学开放在哪一层仍受国籍、机构与经费限制。"
