          "黑洞质量约为太阳的一百万倍，事件位置离星系中心超过 30,000 光年。",
          "Zwicky Transient Facility 每晚检测约五十万次亮度变化，AI 筛选算法首先标出这次位置异常的潮汐撕裂候选。",
          "闪光在数月内的紫外亮度一度超过整个宿主星系，约相当于一百亿个太阳的光。",
          "Swift 的紫外光学望远镜测得辐射温度约为 30,000 摄氏度，跨波段数据共同排除了其他主要解释。",
