        "whyItMatters": "100 天活动、三年周期与 128 家商户的长期处境共同说明，游客增加不是振兴的自动同义词；关键在于峰值之后，收入、交通和关系是否仍可持续。可以把每座岛的旺季人流、淡季营业、渡轮班次、居民参与和决策权放进年度时间轴，比较谁有能力吸收节庆收益，谁在替城市文化消费承担间歇成本。"
