          "团队比较干燥与含冰模拟月壤在月球式低温真空中的微观弯曲和变形。",
          "组合模型目前描述月面以下约 800 米范围，并预测不同冰沉积会留下不同地震信号。",
          "计划中的 VIPER 月球车钻头会产生震动，导航加速度计可尝试测量短频地震波。其他仪器主要直接探测上部约一米的冰。",
