        "sourceDate": "研究解读与 Science Advances 论文发布 2026-07-31",
        "whyItMatters": "15 英寸实验腔、800 米模型深度与未来月球车的钻头和传感器构成一条从实验室到月面的证据链，说明“找水”先要解决怎样解释间接信号。可以把上部一米的直接探测和更深处的地震推断分层显示，继续比较每种方法能看见什么、需要什么校准，以及谁决定冰被用于科学、生命支持还是资源开发。"
