          "团队在 27 个月中举行七场活动，形式源于 2020 年以后线上研讨会暴露的参与不足问题。",
          "一场案例回看 Michael Crommie 团队 2010 年的应变石墨烯论文。Crommie 说明发现最初是偶然出现，随后经历数月困惑。",
          "他还谈到两个各持续约两年却从未发表的失败项目。正式文献中没有这些工作的记录。",
          "配套网站面向所有学科开放。每场录像分配可引用 DOI。Crommie 场次时长为 92 分钟。",
