        "whyItMatters": "参与者怎样听见差异，会影响他们怎样发出差异：beat–bit 主要依赖时长，bat–bet 则更依赖音质。外语发音训练因此不能只要求学习者反复模仿口型，还要先帮助他们听出每一组声音真正依赖的线索。",
